create table if not exists public.app_state (
  id integer primary key check (id = 1),
  data jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.app_state enable row level security;
drop policy if exists "public cannot read app_state directly" on public.app_state;
drop policy if exists "public cannot write app_state directly" on public.app_state;
